const rawMarkdown = $json.data?.markdown || $json.markdown || '';

function normalizeMarkdown(input = '') {
  return input
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/Last updated:?.*/gi, '')
    .replace(/Updated on:?.*/gi, '')
    .replace(/Cookie(s)? .*/gi, '')
    .trim()
    .toLowerCase();
}

$json.normalized_markdown = normalizeMarkdown(rawMarkdown);
return $json;

const rawMarkdown = $json.data?.markdown || $json.markdown || '';
const currentHash = $json.current_hash || '';
const previousHash = $('Limite test').all()[$itemIndex].json.dernier_hash || '';
const previousExcerpt = $('Limite test').all()[$itemIndex].json.dernier_excerpt || '';
const prevErrors = Number($('Limite test').all()[$itemIndex].json.nb_erreurs_consecutives) || 0;

const isError = !rawMarkdown || rawMarkdown.length < 500;
const isBaseline = !isError && !previousHash;
const hasChanged = !isError && !isBaseline && currentHash !== previousHash;

const status = isError
  ? 'error'
  : isBaseline
    ? 'baseline'
    : hasChanged
      ? 'changed'
      : 'unchanged';

const consecutiveErrors = isError ? prevErrors + 1 : 0;

$json.current_hash = currentHash;
$json.previous_hash = previousHash;
$json.markdown_excerpt = rawMarkdown.slice(0, 8000);
$json.previous_excerpt = previousExcerpt;
$json.status = status;
$json.consecutive_errors = consecutiveErrors;
$json.should_run_llm = status === 'changed';
$json.should_snapshot = ['baseline', 'changed', 'error'].includes(status);
$json.should_update_hash = ['baseline', 'changed'].includes(status);
$json.should_alert_tech = consecutiveErrors >= 3;
return $json;

let text = $json.text || '';
text = text.replace(/^```json\s*/i, '').replace(/```$/, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (e) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    try {
      parsed = JSON.parse(text.substring(start, end + 1));
    } catch (e2) {
      parsed = {
        type_changement: "Erreur de parsing",
        resume: "Impossible de parser le JSON retourné par l'IA. Texte brut : " + text.slice(0, 200),
        impact_schoolswp: "Aucun",
        score: 1,
        action_recommandee: "Vérifier manuellement",
        contenu_suggere: "",
        niveau_confiance: "Faible",
        a_verifier_manuellement: "Oui"
      };
    }
  } else {
    parsed = {
      type_changement: "Erreur de parsing",
      resume: "Aucun objet JSON trouvé dans la réponse de l'IA. Texte brut : " + text.slice(0, 200),
      impact_schoolswp: "Aucun",
      score: 1,
      action_recommandee: "Vérifier manuellement",
      contenu_suggere: "",
      niveau_confiance: "Faible",
      a_verifier_manuellement: "Oui"
    };
  }
}
$json.output = parsed;
return $json;

